    out.clockUserSet = raw.clockUserSet === true;
    out.compactClock = (typeof raw.compactClock === 'boolean') ? raw.compactClock : true;
    if (!out.clockUserSet) out.compactClock = true;
    if (typeof raw.showNames !== 'boolean') out.showNames = true;
    else out.showNames = raw.showNames;
    if (typeof raw.exportWithBg === 'boolean') out.exportWithBg = raw.exportWithBg;
    // v1.9.0 起默认把背景图片一起导出；用户手动关掉才不再带
    out.exportBgUserSet = raw.exportBgUserSet === true;
